import{_ as o,Y as i,o as n,c as a,aA as r,H as s}from"./chunks/framework.C6iXY4oq.js";import"./chunks/theme.DxPpgtNj.js";const b=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),d={name:"en/guide/home.md"};function c(l,t,p,h,u,f){const e=i("NolebaseGitChangelog");return n(),a("div",null,[t[0]||(t[0]=r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p>This is an Android notification icon project that provides standardized monochrome icon resources for apps and vendor systems that do not conform to the Android standard notification design.</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>This project was created to bring order to the fragmented third-party app ecosystem, so that third-party app notification icons can also follow the Android standard notification icon design guidelines.</p><p>At its root, the problem is the ecosystem fragmentation caused by MIUI&#39;s non-standard Xiaomi Push notification icons. Other vendors have not fully resolved it either. Instead, most adopted Apple&#39;s approach of using an app&#39;s launcher icon as its primary notification icon, a deceptive kind of &quot;solution&quot;. vivo maintained its own set of monochrome notification icons, but gradually abandoned that approach in later versions of OriginOS.</p><p>As the project lead, I believe Google is responsible for this problem. Android clearly specifies notification icon design guidelines, but Google has not enforced them on vendors, allowing vendors to undermine the standard notification icon design without constraint.</p><p>Most ironically, Google itself abandoned the mandatory notification icon tinting guideline in Android 16 and set notification icons in the notification panel to app launcher icons, completing its wholesale concession to the ecosystem.</p><p>This project began in 2022 under the name <strong>AndroidNotifyIconAdapt</strong>. That ill-fitting name once left the project with resources but no standards. It has now been officially renamed <strong>Android Notification Icon Project</strong> (codenamed <strong>ANIP</strong>) and its original icon resource rules have been completely revised. The project will now move toward more modern, continuous community maintenance.</p><p>This project has been changed from the original <strong>AGPL-3.0</strong> license to <strong>Apache-2.0</strong>. ANIP will continue to be open under the current license, and anyone can use, modify, and distribute the resources of this project in compliance with the license. Changes to the license do not automatically apply to previous versions.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>ANIP currently uses community-supported Xposed modules to adapt the System UI and provides community-maintained monochrome notification icon resources and rules for third-party apps, games, and system apps.</p><p>The following are the current support paths of ANIP. In the future, these Xposed modules will be consolidated into a unified aggregate module maintained by the <a href="https://github.com/BetterAndroid" target="_blank" rel="noreferrer">BetterAndroid</a> organization.</p><ol><li>Ready-to-use Xposed modules</li></ol><ul><li>For HyperOS/MIUI, see <a href="https://github.com/fankes/MIUINativeNotifyIcon" target="_blank" rel="noreferrer">MIUINativeNotifyIcon</a></li><li>For ColorOS, Realme UI, or OxygenOS (&gt;= 12), see <a href="https://github.com/fankes/ColorOSNotifyIcon" target="_blank" rel="noreferrer">ColorOSNotifyIcon</a></li></ul><ol start="2"><li>Adaptation requests proposed by the community</li></ol><ul><li>For AOSP-based and Pixel devices, see <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/102" target="_blank" rel="noreferrer">this issue</a></li><li>For Flyme, see <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/201" target="_blank" rel="noreferrer">this issue</a></li><li>For OneUI, see <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues/475" target="_blank" rel="noreferrer">this issue</a></li></ul><p>ANIP provides icon resource downloads and application through the <a href="./../sdk/quick-start">Official SDK</a>, allowing you to use this SDK to build your own Xposed module or notification adaptation solution.</p><p>If you are a user, you can download and experience the <a href="https://github.com/BetterAndroid/android-notification-icon-project/blob/main/sdk/samples/demo/release" target="_blank" rel="noreferrer">ANIP Demo</a>.</p><h2 id="noncompliant-systems" tabindex="-1">Noncompliant Systems <a class="header-anchor" href="#noncompliant-systems" aria-label="Permalink to &quot;Noncompliant Systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Version</th><th>Violation</th></tr></thead><tbody><tr><td>Stock Android</td><td>&gt;= 16</td><td>Replaces notification icons with app launcher icons in the notification center</td></tr><tr><td>EMUI</td><td>4.0, 4.0.1, 4.1</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>HarmonyOS</td><td>&gt;= 4.0</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>ColorOS<br>OxygenOS</td><td>&gt;= 15.0.1</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>RealmeUI</td><td>&gt;= 6.0</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>MIUI</td><td>&lt;= 9, &gt;= 12.5</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>HyperOS</td><td>All</td><td>Whitelists system apps and replaces third-party notification icons with app launcher icons</td></tr><tr><td>OneUI</td><td>&gt;= 6.0</td><td>Replaces notification icons with app launcher icons in the notification center (can be disabled)</td></tr><tr><td>ZUI</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>Nubia UI</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>RedMagicOS</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>360 OS</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>CoolOS</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>WaterOS</td><td>All</td><td>Replaces all notification icons with app launcher icons</td></tr><tr><td>Flyme</td><td>All</td><td>Whitelists system and third-party apps</td></tr><tr><td>OriginOS</td><td>&gt;= 6</td><td>Replaces all notification icons with app launcher icons</td></tr></tbody></table><h2 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h2><p>The maintenance of this project is inseparable from the support and contributions of all developers.</p><p>If possible, feel free to submit a PR to contribute features you think are needed to this project, or go to <a href="https://github.com/BetterAndroid/android-notification-icon-project/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to make suggestions to us.</p>',23)),s(e)])}const y=o(d,[["render",c]]);export{b as __pageData,y as default};
